#!/usr/bin/python3 -I
"""gen-latdic.py RULES.dic OUT.h: ru_normalizr's latinization_rules.dic (MIT) as a C string."""
import sys

data = open(sys.argv[1], "rb").read()
data.decode("utf-8")
with open(sys.argv[2], "w", encoding="ascii") as f:
    f.write("/* generated by gen-latdic.py from ru_normalizr dictionaries/latinization/"
            "latinization_rules.dic (MIT); do not edit */\n")
    f.write("static const char RN_LATIN_DIC[] =\n")
    for line in data.splitlines(keepends=True):
        f.write('\t"%s"\n' % "".join(chr(b) if 0x20 <= b < 0x7F and b not in b'"\\?' else
                                     "\\%03o" % b for b in line))
    f.write(";\n")
